package com.bike.server.system;
import java.time.LocalDateTime;
public class RoleView { private Long id; private String roleCode; private String roleName; private boolean enabled; private int permissionCount; private LocalDateTime createdAt; private LocalDateTime updatedAt; public Long getId(){return id;} public void setId(Long v){id=v;} public String getRoleCode(){return roleCode;} public void setRoleCode(String v){roleCode=v;} public String getRoleName(){return roleName;} public void setRoleName(String v){roleName=v;} public boolean isEnabled(){return enabled;} public void setEnabled(boolean v){enabled=v;} public int getPermissionCount(){return permissionCount;} public void setPermissionCount(int v){permissionCount=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} public LocalDateTime getUpdatedAt(){return updatedAt;} public void setUpdatedAt(LocalDateTime v){updatedAt=v;} }
